/**
 * Global sprite rendering toggle
 */
export let SPRITE_RENDERING_ENABLED = true;

export function setSpriteRendering(enabled: boolean): void {
  SPRITE_RENDERING_ENABLED = enabled;
}

/**
 * Render conviction energy and global special cooldown beneath a health bar.
 */
export function renderSpecialMeter(
  ctx: CanvasRenderingContext2D,
  fighter: Fighter,
  x: number,
  y: number,
  width: number,
  color: string,
  isPlayer2 = false
): void {
  const energyGauge = resolveHudGauge({
    value: fighter.specialState.currentEnergy,
    max: fighter.specialState.maxEnergy,
    direction: isPlayer2 ? 'reverse' : 'forward',
  });
  const cooldownGauge = resolveHudGauge({
    value: fighter.specialMaxCooldown - fighter.specialCooldown,
    max: fighter.specialMaxCooldown,
    direction: isPlayer2 ? 'reverse' : 'forward',
  });
  const ready = fighter.specialCooldown <= 0;

  ctx.fillStyle = 'rgba(13, 5, 24, 0.88)';
  ctx.fillRect(x, y, width, 8);
  ctx.fillStyle = color;
  const energyWidth = width * energyGauge.ratio;
  ctx.fillRect(isPlayer2 ? x + width - energyWidth : x, y, energyWidth, 8);

  ctx.fillStyle = '#241533';
  ctx.fillRect(x, y + 12, width, 3);
  ctx.fillStyle = ready ? '#39FF14' : '#FF9F1C';
  const cooldownWidth = width * cooldownGauge.ratio;
  ctx.fillRect(isPlayer2 ? x + width - cooldownWidth : x, y + 12, cooldownWidth, 3);

  ctx.font = `800 8px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = ready ? '#39FF14' : '#B8A9C9';
  ctx.textAlign = isPlayer2 ? 'right' : 'left';
  ctx.fillText(
    ready
      ? `SPECIAL READY · ${Math.round(fighter.specialState.currentEnergy)} CONVICTION`
      : `SPECIAL ${Math.ceil(fighter.specialCooldown / 60)}s · ${Math.round(fighter.specialState.currentEnergy)} CONVICTION`,
    isPlayer2 ? x + width : x,
    y + 27
  );
}

/**
 * Per-fighter animation player state cache
 */
const fighterAnimationStateCache = new Map<string, ReturnType<typeof createAnimationPlayerState>>();

interface SpriteClipTransition {
  clip: AnimationClip;
  frame: number;
  ttl: number;
  totalTtl: number;
}

export interface FighterAnimationSnapshot {
  fighterId: string;
  state: string;
  clipId: string;
  clipFrame: number;
  clipFrameCount: number;
  atlasFrameIndex: number;
  nextAtlasFrameIndex: number;
  frameBlend: number;
  playbackSpeed: number;
  attackPhase: AttackPhase | null;
  attackPhaseProgress: number;
  transitionFromClipId: string | null;
  transitionAlpha: number;
  depthScale: number;
  stretchX: number;
  stretchY: number;
  afterImageAlpha: number;
  poseProgress: number | null;
  landingProgress: number;
  turnaroundAmount: number;
  turnScaleX: number;
  rotation: number;
  actionOffsetX: number;
  actionOffsetY: number;
  motionBlur: number;
  impactPulse: number;
}

const fighterClipTransitionCache = new Map<string, SpriteClipTransition>();
const fighterAnimationSnapshotCache = new Map<string, FighterAnimationSnapshot>();

export function getFighterAnimationSnapshot(fighterId: string): FighterAnimationSnapshot | null {
  return fighterAnimationSnapshotCache.get(fighterId) ?? null;
}

function smoothStep01(value: number): number {
  const clamped = Math.max(0, Math.min(1, value));
  return clamped * clamped * (3 - 2 * clamped);
}

function resolveNextClipFrame(
  clip: AnimationClip,
  currentFrame: number,
  direction: 1 | -1
): number {
  if (clip.frames.length <= 1) return currentFrame;
  if (clip.mode === 'loop') return (currentFrame + 1) % clip.frames.length;
  if (clip.mode === 'pingpong') {
    if (direction === 1) return Math.min(clip.frames.length - 1, currentFrame + 1);
    return Math.max(0, currentFrame - 1);
  }
  return Math.min(clip.frames.length - 1, currentFrame + 1);
}

function resolveSpriteFrameBlend(
  animationState: ReturnType<typeof createAnimationPlayerState>,
  combatProgress: number | null
): { nextFrame: number; blend: number } {
  const clip = animationState.currentClip;
  if (!clip || clip.frames.length <= 1) {
    return { nextFrame: animationState.currentFrame, blend: 0 };
  }

  if (combatProgress !== null) {
    const framePosition = Math.max(0, Math.min(1, combatProgress)) * (clip.frames.length - 1);
    const currentFrame = Math.min(clip.frames.length - 1, Math.floor(framePosition));
    const localProgress = framePosition - currentFrame;
    return {
      nextFrame: Math.min(clip.frames.length - 1, currentFrame + 1),
      blend: smoothStep01((localProgress - 0.42) / 0.58),
    };
  }

  const currentClipFrame = clip.frames[animationState.currentFrame];
  const localProgress = currentClipFrame
    ? animationState.frameTimer / Math.max(1, currentClipFrame.duration)
    : 0;
  return {
    nextFrame: resolveNextClipFrame(clip, animationState.currentFrame, animationState.direction),
    blend: smoothStep01((localProgress - 0.46) / 0.54),
  };
}

/**
 * Get or create animation player state for a fighter
 */
function getFighterAnimationState(
  fighterId: string
): ReturnType<typeof createAnimationPlayerState> {
  const cached = fighterAnimationStateCache.get(fighterId);
  if (cached) {
    return cached;
  }

  const created = createAnimationPlayerState();
  fighterAnimationStateCache.set(fighterId, created);
  return created;
}

/**
 * Clear animation state cache (call on reset)
 */
export function clearFighterAnimationCache(): void {
  fighterAnimationStateCache.clear();
  fighterClipTransitionCache.clear();
  fighterAnimationSnapshotCache.clear();
}

/**
 * Render context
 */
export interface RenderContext {
  ctx: CanvasRenderingContext2D;
  camera: Camera;
  frame: number;
  deltaTime: number;
}

/**
 * Clear the canvas
 */
export function clearCanvas(ctx: CanvasRenderingContext2D): void {
  ctx.fillStyle = '#1A0A2E';
  ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
}

/**
 * Render background with parallax
 */
export function renderBackground(
  ctx: CanvasRenderingContext2D,
  camera: Camera,
  frame = 0,
  profile: FightGraphicsProfile = resolveFightGraphicsProfile()
): void {
  renderFightBackdrop(ctx, camera, frame, profile);
}

/**
 * Render ground/arena
 */
export function renderArena(
  ctx: CanvasRenderingContext2D,
  _camera: Camera,
  profile: FightGraphicsProfile = resolveFightGraphicsProfile(),
  frame = 0
): void {
  // Ground
  ctx.fillStyle = profile.floorColor;
  ctx.fillRect(0, CANVAS_HEIGHT - 100, CANVAS_WIDTH, 100);

  const floorGradient = ctx.createLinearGradient(0, CANVAS_HEIGHT - 100, 0, CANVAS_HEIGHT);
  floorGradient.addColorStop(0, `${profile.floorHighlight}88`);
  floorGradient.addColorStop(1, `${profile.floorColor}00`);
  ctx.fillStyle = floorGradient;
  ctx.fillRect(0, CANVAS_HEIGHT - 100, CANVAS_WIDTH, 100);

  // Lane lines
  ctx.strokeStyle = `${profile.floorHighlight}AA`;
  ctx.lineWidth = 1;
  ctx.setLineDash([10, 10]);

  for (let lane = 0; lane < 3; lane++) {
    const y = getLaneGroundY(lane as 0 | 1 | 2);
    ctx.beginPath();
    ctx.moveTo(0, y);
    ctx.lineTo(CANVAS_WIDTH, y);
    ctx.stroke();
  }

  ctx.setLineDash([]);

  const stageEvent = resolveFightStageEvent(frame, profile);
  ctx.save();
  ctx.globalAlpha = 0.16 + stageEvent.intensity * 0.12;
  ctx.strokeStyle = profile.accent;
  ctx.lineWidth = 1;
  for (let ray = 0; ray <= 12; ray += 1) {
    const x = (CANVAS_WIDTH / 12) * ray;
    ctx.beginPath();
    ctx.moveTo(CANVAS_WIDTH / 2, CANVAS_HEIGHT - 100);
    ctx.lineTo(x, CANVAS_HEIGHT);
    ctx.stroke();
  }

  if (profile.id === 'babylon_market') {
    ctx.strokeStyle = `${profile.secondaryAccent}99`;
    ctx.lineWidth = 3;
    for (const x of [180, 780]) {
      const offset = Math.sin(frame * 0.025 + x) * 8;
      ctx.beginPath();
      ctx.moveTo(x + offset, CANVAS_HEIGHT - 100);
      ctx.lineTo(x - 54 + offset, CANVAS_HEIGHT);
      ctx.stroke();
    }
  } else if (profile.id === 'babylon_archive') {
    ctx.fillStyle = `${profile.accent}22`;
    for (let row = 0; row < 3; row += 1) {
      for (let column = 0; column < 12; column += 1) {
        const pulse = 0.35 + Math.sin(frame * 0.06 + row * 2 + column) * 0.2;
        ctx.globalAlpha = pulse + stageEvent.intensity * 0.16;
        ctx.fillRect(18 + column * 80, CANVAS_HEIGHT - 92 + row * 29, 48, 7);
      }
    }
  } else if (profile.id === 'babylon_gate') {
    ctx.strokeStyle = `${profile.secondaryAccent}88`;
    ctx.lineWidth = 2;
    for (let crack = 0; crack < 9; crack += 1) {
      const baseX = 80 + crack * 106;
      ctx.beginPath();
      ctx.moveTo(baseX, CANVAS_HEIGHT - 98);
      ctx.lineTo(baseX + 12, CANVAS_HEIGHT - 72);
      ctx.lineTo(baseX - 8, CANVAS_HEIGHT - 42);
      ctx.lineTo(baseX + 20, CANVAS_HEIGHT - 8);
      ctx.stroke();
    }
  } else {
    ctx.strokeStyle = `${profile.secondaryAccent}66`;
    for (let y = CANVAS_HEIGHT - 88; y < CANVAS_HEIGHT; y += 20) {
      const drift = (frame * 0.45 + y) % 40;
      ctx.beginPath();
      ctx.moveTo(-40 + drift, y);
      ctx.lineTo(CANVAS_WIDTH, y);
      ctx.stroke();
    }
  }
  ctx.restore();

  // Arena edges (glowing)
  const edgeGradientLeft = ctx.createLinearGradient(0, 0, 50, 0);
  edgeGradientLeft.addColorStop(0, `${profile.secondaryAccent}44`);
  edgeGradientLeft.addColorStop(1, 'transparent');
  ctx.fillStyle = edgeGradientLeft;
  ctx.fillRect(0, 0, 50, CANVAS_HEIGHT);

  const edgeGradientRight = ctx.createLinearGradient(CANVAS_WIDTH - 50, 0, CANVAS_WIDTH, 0);
  edgeGradientRight.addColorStop(0, 'transparent');
  edgeGradientRight.addColorStop(1, `${profile.accent}44`);
  ctx.fillStyle = edgeGradientRight;
  ctx.fillRect(CANVAS_WIDTH - 50, 0, 50, CANVAS_HEIGHT);
}

/**
 * Render a fighter with sprite or procedural fallback
 */
export function renderFighter(
  ctx: CanvasRenderingContext2D,
  fighter: Fighter,
  camera: Camera,
  frame = 0,
  flashScale = 1
): void {
  const animMap = getCharacterAnimationMap(fighter.characterId as CharacterId);

  const useSprites =
    SPRITE_RENDERING_ENABLED && animMap && canRenderSprites(animMap, fighter.characterId);

  if (useSprites) {
    renderFighterWithSprite(ctx, fighter, animMap, frame, flashScale);
  } else {
    fighterAnimationSnapshotCache.delete(fighter.id);
    renderFighterProcedural(ctx, fighter, camera, frame, flashScale);
  }
}

function getNamedAnimationClip(
  animMap: CharacterAnimationMap,
  clipId: string
): AnimationClip | null {
  return animMap.manifest.clips.find((clip) => clip.id === clipId) ?? null;
}

function resolveAuthoredAnimationV2Clip(
  fighter: Fighter,
  animMap: CharacterAnimationMap,
  currentClip: AnimationClip | null,
  currentClipIsPlaying: boolean
): AnimationClip | null {
  const hasAuthoredLocomotion =
    getNamedAnimationClip(animMap, 'walk_forward_v2') !== null ||
    getNamedAnimationClip(animMap, 'run_v2') !== null ||
    getNamedAnimationClip(animMap, 'jump_takeoff_v2') !== null;
  if (!hasAuthoredLocomotion) return null;

  if (fighter.laneChangeTimer > 0 && fighter.laneChangeStartLane !== fighter.targetLane) {
    const laneClip = getNamedAnimationClip(
      animMap,
      fighter.targetLane > fighter.laneChangeStartLane ? 'lane_away_v2' : 'lane_toward_v2'
    );
    if (laneClip) return laneClip;
  }

  if (fighter.state === 'walking') {
    const signedVelocity = fighter.moveVelocityX + fighter.velocityX;
    const facingDirection = fighter.facing === 'right' ? 1 : -1;
    const isBackingAway = signedVelocity !== 0 && Math.sign(signedVelocity) !== facingDirection;
    return getNamedAnimationClip(animMap, isBackingAway ? 'walk_backward_v2' : 'walk_forward_v2');
  }

  if (fighter.state === 'running') {
    return getNamedAnimationClip(animMap, fighter.stateFrame < 12 ? 'run_start_v2' : 'run_v2');
  }

  if (fighter.state === 'idle') {
    if (currentClip?.id === 'run_stop_v2') {
      return currentClipIsPlaying ? currentClip : null;
    }
    if (currentClip?.id === 'run_start_v2' || currentClip?.id === 'run_v2') {
      return getNamedAnimationClip(animMap, 'run_stop_v2');
    }
  }

  return null;
}

/**
 * Render fighter with sprite system
 */
function renderFighterWithSprite(
  ctx: CanvasRenderingContext2D,
  fighter: Fighter,
  animMap: CharacterAnimationMap,
  frame: number,
  flashScale: number
): void {
  const animState = getFighterAnimationState(fighter.id);
  let targetClip: ReturnType<typeof getStateClip> | ReturnType<typeof getAttackPhaseClip> | null =
    null;
  let attackPhase: AttackPhase | null = null;
  let attackPhaseProgress = 0;
  let poseProgress: number | null = null;
  let effectiveState = fighter.state as string;

  if (fighter.state === 'attacking' || fighter.state === 'special') {
    if (fighter.currentAttack) {
      attackPhase = resolveAttackPhase(
        fighter.attackFrame,
        fighter.currentAttack.startup,
        fighter.currentAttack.active,
        fighter.currentAttack.recovery
      );
      attackPhaseProgress = resolveAttackPhaseProgress(
        fighter.attackFrame,
        fighter.currentAttack.startup,
        fighter.currentAttack.active,
        fighter.currentAttack.recovery
      );
      targetClip = getAttackPhaseClip(
        animMap,
        fighter.currentAttack.id,
        attackPhase,
        fighter.currentAttack.type
      );
      poseProgress = attackPhaseProgress;
    }
  }

  if (fighter.landingFrames > 0 && fighter.isGrounded && !fighter.currentAttack) {
    effectiveState = 'landing';
    const landingProgress =
      1 - Math.min(1, fighter.landingFrames / FRAME_DATA.LANDING_IMPACT_DURATION);
    const landingClip = getNamedAnimationClip(animMap, 'land_v2');
    const recoveryClip = getNamedAnimationClip(animMap, 'land_recovery_v2');
    if (landingClip && recoveryClip) {
      const isRecovery = landingProgress >= 0.5;
      targetClip = isRecovery ? recoveryClip : landingClip;
      poseProgress = isRecovery ? (landingProgress - 0.5) * 2 : landingProgress * 2;
    } else {
      targetClip = getStateClip(animMap, 'landing');
      poseProgress = landingProgress;
    }
  } else if (!targetClip && fighter.turnaroundFrames > 0) {
    const turnClip = getNamedAnimationClip(
      animMap,
      fighter.facing === 'right' ? 'turn_right_v2' : 'turn_left_v2'
    );
    if (turnClip) {
      effectiveState = 'idle';
      targetClip = turnClip;
      poseProgress = 1 - Math.min(1, fighter.turnaroundFrames / FRAME_DATA.TURNAROUND_DURATION);
    }
  } else if (!targetClip) {
    targetClip = resolveAuthoredAnimationV2Clip(
      fighter,
      animMap,
      animState.currentClip,
      animState.isPlaying
    );
    if (targetClip && fighter.laneChangeTimer > 0) {
      poseProgress = 1 - fighter.laneChangeTimer / FRAME_DATA.LANE_CHANGE_DURATION;
      effectiveState = 'walking';
    }
    targetClip ??= getStateClip(animMap, fighter.state);
    if (fighter.state === 'gettingUp') {
      poseProgress = Math.min(1, fighter.stateFrame / Math.max(1, FRAME_DATA.GET_UP_DURATION - 1));
    } else if (fighter.state === 'knockdown') {
      poseProgress = Math.min(
        1,
        fighter.stateFrame / Math.max(1, Math.floor(FRAME_DATA.KNOCKDOWN_DURATION * 0.35))
      );
    } else if (fighter.state === 'jumping') {
      poseProgress = Math.max(0, Math.min(0.48, 1 - fighter.velocityY / FRAME_DATA.JUMP_VELOCITY));
    } else if (fighter.state === 'falling') {
      poseProgress = Math.max(
        0.52,
        Math.min(1, 0.52 + (-fighter.velocityY / FRAME_DATA.JUMP_VELOCITY) * 0.48)
      );
    }
  }
  const effectiveClip = targetClip;
  const locomotionSpeed = Math.abs(fighter.moveVelocityX) + Math.abs(fighter.velocityX) * 0.35;
  const targetPlaybackSpeed = resolveAnimationPlaybackTarget(effectiveState, locomotionSpeed);
  const needsClipChange =
    effectiveClip !== null &&
    shouldRestartAnimationClip(animState.currentClip?.id ?? null, effectiveClip.id);

  if (effectiveClip && needsClipChange) {
    if (animState.currentClip) {
      const transitionFrames = resolveClipTransitionFrames(
        animState.currentClip.id,
        effectiveClip.id
      );
      fighterClipTransitionCache.set(fighter.id, {
        clip: animState.currentClip,
        frame: animState.currentFrame,
        ttl: transitionFrames,
        totalTtl: transitionFrames,
      });
    }
    const newState = playClip(animState, effectiveClip, targetPlaybackSpeed);
    Object.assign(animState, newState);
  } else if (effectiveClip) {
    const playbackSpeed = smoothAnimationPlaybackSpeed(
      animState.playbackSpeed,
      targetPlaybackSpeed
    );
    Object.assign(animState, setPlaybackSpeed(animState, playbackSpeed));
  }

  if (poseProgress !== null) {
    Object.assign(animState, seekToProgress(animState, poseProgress));
    animState.isPlaying = true;
  } else {
    const updatedState = updateAnimationPlayer(animState, 1);
    Object.assign(animState, updatedState);
  }

  const frameBlendState = resolveSpriteFrameBlend(animState, poseProgress);

  const screenX = fighter.x;
  const screenY = fighter.getWorldY();
  const facingRight = fighter.facing === 'right';
  const animation = createFighterAnimationView(fighter, frame);
  if (!animState.currentClip || !animMap.atlas) {
    console.warn(`Missing clip or atlas for ${fighter.characterId}, falling back to procedural`);
    renderFighterProcedural(
      ctx,
      fighter,
      { x: 0, y: 0, zoom: 1, shakeOffsetX: 0, shakeOffsetY: 0 } as Camera,
      frame,
      flashScale
    );
    return;
  }

  const spriteAtlas = animMap.atlas;
  const activeClipFrame = animState.currentClip.frames[animState.currentFrame];
  const activeAtlasFrame = activeClipFrame ? getAtlasFrame(animMap, activeClipFrame) : null;
  const depthScale = activeAtlasFrame
    ? resolveFighterSpriteRenderScale(
        spriteAtlas,
        animation.depthScale,
        getSpriteScaleFactor(),
        activeAtlasFrame
      )
    : animation.depthScale;

  const stretchX = Math.max(0.86, Math.min(1.16, 1 + (animation.bodyWidthScale - 1) * 0.28));
  const stretchY = Math.max(0.86, Math.min(1.16, 1 + (animation.bodyHeightScale - 1) * 0.24));
  const airborneTilt = fighter.isGrounded
    ? 0
    : Math.max(-0.09, Math.min(0.09, -fighter.velocityY * 0.008));
  const rotation = Math.max(
    -0.18,
    Math.min(0.18, animation.bodyLean * 0.18 + animation.bodyTwist * 0.1 + airborneTilt)
  );
  const turnaroundPhase = animation.turnaroundAmount > 0 ? 1 - animation.turnaroundAmount : 1;
  const turnScaleX =
    animation.turnaroundAmount > 0
      ? 0.26 + Math.abs(Math.cos(turnaroundPhase * Math.PI)) * 0.74
      : 1;
  const turnGhostAlpha =
    animation.turnaroundAmount > 0 ? Math.sin(turnaroundPhase * Math.PI) * 0.34 : 0;
  const facingSign = facingRight ? 1 : -1;
  const actionOffsetX = animation.actionOffsetX * facingSign;

  ctx.save();
  ctx.globalAlpha = fighter.state === 'knockdown' ? 0.28 : 0.22;
  ctx.fillStyle = '#05030A';
  ctx.translate(screenX + actionOffsetX * 0.24, screenY + 3 + animation.actionOffsetY * 0.12);
  ctx.scale(animation.shadowScaleX, animation.shadowScaleY);
  ctx.beginPath();
  ctx.ellipse(0, 0, 34, 9, 0, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  const drawSpritePose = (
    clip: AnimationClip,
    clipFrame: number,
    offsetX: number,
    opacity: number,
    blur = 0,
    poseFacingRight = facingRight,
    additive = false
  ): boolean => {
    ctx.save();
    ctx.translate(
      screenX + offsetX + animation.recoilOffsetX + actionOffsetX,
      screenY + animation.bobOffsetY + animation.actionOffsetY
    );
    ctx.rotate(rotation);
    ctx.scale(stretchX * turnScaleX, stretchY);
    if (additive) {
      ctx.globalCompositeOperation = 'screen';
    }
    if (blur > 0) {
      ctx.filter = `blur(${blur}px) saturate(1.35)`;
    } else if (animation.flashIntensity * flashScale > 0) {
      const flashIntensity = animation.flashIntensity * flashScale;
      ctx.filter = `brightness(${1 + flashIntensity * 0.85}) saturate(${1 + flashIntensity * 0.45})`;
    }
    const poseClipFrame = clip.frames[clipFrame];
    const poseAtlasFrame = poseClipFrame ? getAtlasFrame(animMap, poseClipFrame) : null;
    const poseDepthScale = poseAtlasFrame
      ? resolveFighterSpriteRenderScale(
          spriteAtlas,
          animation.depthScale,
          getSpriteScaleFactor(),
          poseAtlasFrame
        )
      : depthScale;
    const result = renderFighterSprite(
      ctx,
      animMap,
      clip,
      clipFrame,
      0,
      0,
      poseFacingRight,
      poseDepthScale,
      opacity,
      fighter.characterId
    );
    ctx.restore();
    return result;
  };

  const currentClip = animState.currentClip;
  const transition = fighterClipTransitionCache.get(fighter.id);
  const transitionAlpha = transition ? transition.ttl / transition.totalTtl : 0;
  if (transition && transitionAlpha > 0) {
    drawSpritePose(transition.clip, transition.frame, 0, transitionAlpha * 0.28, 0.38);
  }
  if (turnGhostAlpha > 0.02) {
    drawSpritePose(currentClip, animState.currentFrame, 0, turnGhostAlpha, 0.55, !facingRight);
  }

  const velocity = fighter.moveVelocityX + fighter.velocityX;
  const trailDirection = velocity === 0 ? (facingRight ? -1 : 1) : velocity > 0 ? -1 : 1;
  const trailAlpha = Math.max(animation.afterImageAlpha, animation.motionBlur * 0.32);
  const trailDistance = 10 + animation.motionBlur * 18;
  if (trailAlpha > 0.04) {
    drawSpritePose(
      currentClip,
      animState.currentFrame,
      trailDirection * trailDistance,
      trailAlpha * 0.36,
      1.2 + animation.motionBlur * 1.2,
      facingRight,
      true
    );
    drawSpritePose(
      currentClip,
      animState.currentFrame,
      trailDirection * trailDistance * 0.52,
      trailAlpha * 0.62,
      0.55 + animation.motionBlur * 0.55,
      facingRight,
      true
    );
  }

  const hasFrameBlend =
    frameBlendState.nextFrame !== animState.currentFrame && frameBlendState.blend > 0.01;
  const frameBlendOpacity = hasFrameBlend ? frameBlendState.blend * 0.82 : 0;
  const rendered = drawSpritePose(currentClip, animState.currentFrame, 0, 1 - frameBlendOpacity);
  if (hasFrameBlend) {
    drawSpritePose(currentClip, frameBlendState.nextFrame, 0, frameBlendOpacity);
  }

  const currentAtlasFrame = currentClip.frames[animState.currentFrame]?.frameIndex ?? -1;
  const nextAtlasFrame =
    currentClip.frames[frameBlendState.nextFrame]?.frameIndex ?? currentAtlasFrame;
  fighterAnimationSnapshotCache.set(fighter.id, {
    fighterId: fighter.id,
    state: effectiveState,
    clipId: currentClip.id,
    clipFrame: animState.currentFrame,
    clipFrameCount: currentClip.frames.length,
    atlasFrameIndex: currentAtlasFrame,
    nextAtlasFrameIndex: nextAtlasFrame,
    frameBlend: frameBlendState.blend,
    playbackSpeed: animState.playbackSpeed,
    attackPhase,
    attackPhaseProgress,
    transitionFromClipId: transition?.clip.id ?? null,
    transitionAlpha,
    depthScale,
    stretchX,
    stretchY,
    afterImageAlpha: animation.afterImageAlpha,
    poseProgress,
    landingProgress:
      fighter.landingFrames > 0
        ? 1 - Math.min(1, fighter.landingFrames / FRAME_DATA.LANDING_IMPACT_DURATION)
        : 0,
    turnaroundAmount: animation.turnaroundAmount,
    turnScaleX,
    rotation,
    actionOffsetX,
    actionOffsetY: animation.actionOffsetY,
    motionBlur: animation.motionBlur,
    impactPulse: animation.impactPulse,
  });

  if (transition) {
    transition.ttl -= 1;
    if (transition.ttl <= 0) fighterClipTransitionCache.delete(fighter.id);
  }

  if (!rendered) {
    // Fall back to procedural rendering when sprites fail
    renderFighterProcedural(
      ctx,
      fighter,
      { x: 0, y: 0, zoom: 1, shakeOffsetX: 0, shakeOffsetY: 0 } as Camera,
      frame,
      flashScale
    );
  }
}

/**
 * Render fighter with procedural animation (original implementation)
 */
function renderFighterProcedural(
  ctx: CanvasRenderingContext2D,
  fighter: Fighter,
  _camera: Camera,
  frame = 0,
  flashScale = 1
): void {
  const character = CHARACTERS[fighter.characterId as keyof typeof CHARACTERS];
  const colors = character?.colors ?? {
    primary: '#00F5FF',
    secondary: '#FF00FF',
    accent: '#39FF14',
  };

  const animation = createFighterAnimationView(fighter, frame);
  const screenX = fighter.x;
  const screenY = fighter.getWorldY() + animation.bobOffsetY;
  const bodyWidth = 42 * animation.bodyWidthScale;
  const bodyHeight = 62 * animation.bodyHeightScale;
  const bodyTop = -bodyHeight - 18;
  const headRadiusX = 18 * animation.headScaleX;
  const headRadiusY = 16 * animation.headScaleY;

  const drawSegmentedLimb = (
    upperAngle: number,
    lowerAngle: number,
    upperLength: number,
    lowerLength: number,
    lineWidth: number,
    strokeStyle: string
  ) => {
    const elbowX = Math.cos(upperAngle) * upperLength;
    const elbowY = Math.sin(upperAngle) * upperLength;
    const handX = elbowX + Math.cos(lowerAngle) * lowerLength;
    const handY = elbowY + Math.sin(lowerAngle) * lowerLength;

    ctx.strokeStyle = strokeStyle;
    ctx.lineWidth = lineWidth;
    ctx.lineCap = 'round';
    ctx.lineJoin = 'round';

    ctx.beginPath();
    ctx.moveTo(0, 0);
    ctx.lineTo(elbowX, elbowY);
    ctx.lineTo(handX, handY);
    ctx.stroke();

    ctx.fillStyle = strokeStyle;
    ctx.beginPath();
    ctx.arc(elbowX, elbowY, Math.max(2, lineWidth * 0.45), 0, Math.PI * 2);
    ctx.fill();
  };

  const drawBody = (ghostAlpha = 1, ghostOffsetX = 0) => {
    ctx.save();
    ctx.translate(ghostOffsetX + animation.recoilOffsetX, 0);
    ctx.globalAlpha *= ghostAlpha;

    if (animation.auraAlpha > 0) {
      ctx.save();
      ctx.globalAlpha *= animation.auraAlpha;
      ctx.fillStyle = colors.accent;
      ctx.shadowColor = colors.accent;
      ctx.shadowBlur = 18;
      ctx.beginPath();
      ctx.ellipse(0, bodyTop + bodyHeight * 0.55, 28, 50, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    ctx.save();
    ctx.translate(0, bodyTop + bodyHeight * 0.5);
    ctx.rotate(animation.bodyLean * 0.15);
    drawSegmentedLimb(
      animation.rearLegAngle,
      animation.rearShinAngle,
      15 + animation.legSwing * 4,
      13 + animation.legSwing * 4,
      6,
      colors.secondary
    );
    ctx.translate(0, -bodyHeight * 0.4);
    drawSegmentedLimb(
      animation.rearArmAngle,
      animation.rearForeArmAngle,
      14 + animation.rearArmReach * 8,
      12 + animation.rearArmReach * 8,
      6,
      colors.secondary
    );
    ctx.restore();

    ctx.save();
    ctx.translate(0, bodyTop + bodyHeight * 0.5);
    ctx.rotate(animation.bodyLean * 0.65);
    ctx.transform(1, 0, animation.bodyTwist * 0.35, 1, 0, 0);
    ctx.fillStyle = colors.primary;
    ctx.fillRect(-bodyWidth / 2, -bodyHeight / 2, bodyWidth, bodyHeight);
    ctx.fillStyle = colors.accent;
    ctx.fillRect(bodyWidth * 0.05, -bodyHeight * 0.35, 5, bodyHeight * 0.7);
    ctx.restore();

    ctx.save();
    ctx.translate(animation.headOffsetX, bodyTop + animation.headOffsetY);
    ctx.rotate(animation.bodyTwist * 0.15);
    ctx.fillStyle = colors.secondary;
    ctx.beginPath();
    ctx.ellipse(0, 0, headRadiusX, headRadiusY, 0, 0, Math.PI * 2);
    ctx.fill();

    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(-8, -4, 6, 4);
    ctx.fillRect(3, -4, 6, 4);
    ctx.fillStyle = colors.accent;
    ctx.fillRect(-7, -2, 4, 2);
    ctx.fillRect(4, -2, 4, 2);
    ctx.restore();

    ctx.save();
    ctx.translate(0, bodyTop + bodyHeight * 0.5);
    ctx.rotate(animation.bodyLean * 0.12);
    drawSegmentedLimb(
      animation.frontLegAngle,
      animation.frontShinAngle,
      16 + animation.legSwing * 5,
      14 + animation.legSwing * 5,
      7,
      colors.primary
    );
    ctx.translate(0, -bodyHeight * 0.38);
    drawSegmentedLimb(
      animation.frontArmAngle,
      animation.frontForeArmAngle,
      15 + animation.frontArmReach * 9,
      13 + animation.frontArmReach * 10,
      7,
      colors.primary
    );
    ctx.restore();

    if (animation.guardArc > 0) {
      ctx.save();
      ctx.globalAlpha *= animation.guardArc;
      ctx.strokeStyle = `${colors.accent}CC`;
      ctx.lineWidth = 4;
      ctx.beginPath();
      ctx.arc(8, bodyTop + bodyHeight * 0.45, 34, -Math.PI / 2, Math.PI / 2);
      ctx.stroke();
      ctx.restore();
    }

    const flashIntensity = animation.flashIntensity * flashScale;
    if (animation.flashColor && flashIntensity > 0) {
      ctx.save();
      ctx.globalAlpha *= flashIntensity;
      ctx.fillStyle = animation.flashColor;
      ctx.beginPath();
      ctx.ellipse(0, bodyTop + bodyHeight * 0.42, 30, 60, 0, 0, Math.PI * 2);
      ctx.fill();
      ctx.restore();
    }

    ctx.restore();
  };

  ctx.save();
  ctx.translate(screenX, screenY);
  ctx.scale(animation.depthScale, animation.depthScale);

  if (fighter.facing === 'left') {
    ctx.scale(-1, 1);
  }

  ctx.fillStyle = 'rgba(0, 0, 0, 0.3)';
  ctx.beginPath();
  ctx.ellipse(0, 0, 26 * animation.shadowScaleX, 8 * animation.shadowScaleY, 0, 0, Math.PI * 2);
  ctx.fill();

  if (animation.afterImageAlpha > 0) {
    drawBody(animation.afterImageAlpha * 0.7, -(fighter.facing === 'right' ? 14 : -14));
    drawBody(animation.afterImageAlpha * 0.45, -(fighter.facing === 'right' ? 24 : -24));
  }

  if (animation.turnaroundAmount > 0.2) {
    drawBody(animation.turnaroundAmount * 0.12, fighter.facing === 'right' ? -10 : 10);
  }

  drawBody();
  ctx.restore();

  // Name label
  ctx.font = `900 12px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = '#FFFFFF';
  ctx.textAlign = 'center';
  ctx.fillText(character?.name ?? 'Fighter', screenX, screenY - 130 * animation.depthScale);
}

/**
 * Render health bar
 */
export function renderHealthBar(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  width: number,
  height: number,
  currentHealth: number,
  maxHealth: number,
  color: string,
  label: string,
  isPlayer2 = false
): void {
  const gauge = resolveHudGauge({
    value: currentHealth,
    max: maxHealth,
    lowThreshold: 0.25,
    criticalThreshold: 0.12,
    direction: isPlayer2 ? 'reverse' : 'forward',
    time: Date.now() / 1000,
    pulsePeriod: 0.63,
  });

  // Background
  ctx.fillStyle = '#1A0A2E';
  ctx.fillRect(x, y, width, height);

  // Health fill
  const fillWidth = width * gauge.ratio;
  if (isPlayer2) {
    ctx.fillStyle = color;
    ctx.fillRect(x + width - fillWidth, y, fillWidth, height);
  } else {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, fillWidth, height);
  }

  // Low health warning
  if (gauge.warning) {
    ctx.fillStyle = '#FF073A';
    ctx.globalAlpha = gauge.pulse;
    if (isPlayer2) {
      ctx.fillRect(x + width - fillWidth, y, fillWidth, height);
    } else {
      ctx.fillRect(x, y, fillWidth, height);
    }
    ctx.globalAlpha = 1;
  }

  // Border
  ctx.strokeStyle = color;
  ctx.lineWidth = 2;
  ctx.strokeRect(x, y, width, height);

  // Label
  ctx.font = 'bold 12px "Courier New", monospace';
  ctx.fillStyle = '#FFFFFF';
  ctx.textAlign = isPlayer2 ? 'right' : 'left';
  ctx.fillText(label, isPlayer2 ? x + width : x, y - 5);

  // Health text
  ctx.font = `800 9px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = '#FFFFFF';
  ctx.textAlign = 'center';
  ctx.fillText(`${Math.ceil(currentHealth)}`, x + width / 2, y + height - 5);
}

/**
 * Render combo display
 */
export function renderComboDisplay(
  ctx: CanvasRenderingContext2D,
  x: number,
  y: number,
  count: number,
  color: string
): void {
  if (count < 2) return;

  const text = getComboDisplayText({ count, damage: 0, lastHitFrame: 0, isActive: true, hits: [] });
  const scale = 1 + Math.min(count * 0.05, 0.3);

  ctx.save();
  ctx.translate(x, y);
  ctx.scale(scale, scale);

  // Glow effect
  ctx.shadowColor = color;
  ctx.shadowBlur = 10;

  ctx.font = 'bold 32px "Courier New", monospace';
  ctx.fillStyle = color;
  ctx.textAlign = 'center';
  ctx.fillText(text, 0, 0);

  ctx.font = 'bold 48px "Courier New", monospace';
  ctx.fillText(`${count} HIT`, 0, 40);

  ctx.shadowBlur = 0;
  ctx.restore();
}

/**
 * Render timer
 */
function renderHudChrome(ctx: CanvasRenderingContext2D): void {
  ctx.save();
  ctx.fillStyle = 'rgba(8, 5, 17, 0.84)';
  ctx.fillRect(34, 8, 332, 84);
  ctx.fillRect(CANVAS_WIDTH - 366, 8, 332, 84);
  ctx.fillStyle = 'rgba(8, 5, 17, 0.94)';
  ctx.fillRect(CANVAS_WIDTH / 2 - 72, 8, 144, 88);
  ctx.strokeStyle = 'rgba(184, 169, 201, 0.32)';
  ctx.lineWidth = 1;
  ctx.strokeRect(34.5, 8.5, 331, 83);
  ctx.strokeRect(CANVAS_WIDTH - 365.5, 8.5, 331, 83);
  ctx.strokeRect(CANVAS_WIDTH / 2 - 71.5, 8.5, 143, 87);
  ctx.fillStyle = '#00F5FF';
  ctx.fillRect(34, 8, 4, 84);
  ctx.fillStyle = '#FF00FF';
  ctx.fillRect(CANVAS_WIDTH - 38, 8, 4, 84);
  ctx.fillStyle = '#FF9F1C';
  ctx.fillRect(CANVAS_WIDTH / 2 - 48, 93, 96, 2);
  ctx.font = `800 8px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = '#B8A9C9';
  ctx.textAlign = 'left';
  ctx.fillText('P1 // DOCTRINE', 50, 24);
  ctx.textAlign = 'right';
  ctx.fillText('P2 // DOCTRINE', CANVAS_WIDTH - 50, 24);
  ctx.restore();
}

export function renderTimer(ctx: CanvasRenderingContext2D, time: number, roundNumber = 1): void {
  const minutes = Math.floor(time / 60);
  const seconds = Math.floor(time % 60);
  const text = `${minutes}:${seconds.toString().padStart(2, '0')}`;

  ctx.font = `800 9px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = '#FF9F1C';
  ctx.textAlign = 'center';
  ctx.fillText(`ROUND ${roundNumber}`, CANVAS_WIDTH / 2, 27);
  ctx.font = `900 30px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = time < 10 ? '#FF073A' : '#FFFFFF';
  ctx.fillText(text, CANVAS_WIDTH / 2, 59);
  ctx.font = `800 8px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = time < 10 ? '#FF4B6E' : '#B8A9C9';
  ctx.fillText(time < 10 ? 'FINAL ARGUMENT' : 'MATCH CLOCK', CANVAS_WIDTH / 2, 81);

  // Flashing warning
  if (time < 10 && Math.floor(Date.now() / 500) % 2 === 0) {
    ctx.fillStyle = '#FF073A44';
    ctx.fillRect(0, 0, CANVAS_WIDTH, 96);
  }
}

/**
 * Render round indicator
 */
export function renderRoundIndicator(
  ctx: CanvasRenderingContext2D,
  p1Wins: number,
  p2Wins: number,
  roundsToWin: number
): void {
  const dotRadius = 8;
  const spacing = 25;
  const centerX = CANVAS_WIDTH / 2;
  const y = 84;

  // Player 1 dots (left side)
  for (let i = 0; i < roundsToWin; i++) {
    const x = centerX - 50 - i * spacing;
    ctx.beginPath();
    ctx.arc(x, y, dotRadius, 0, Math.PI * 2);
    ctx.fillStyle = i < p1Wins ? '#00F5FF' : '#2D1B4E';
    ctx.fill();
    ctx.strokeStyle = '#00F5FF';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // Player 2 dots (right side)
  for (let i = 0; i < roundsToWin; i++) {
    const x = centerX + 50 + i * spacing;
    ctx.beginPath();
    ctx.arc(x, y, dotRadius, 0, Math.PI * 2);
    ctx.fillStyle = i < p2Wins ? '#FF00FF' : '#2D1B4E';
    ctx.fill();
    ctx.strokeStyle = '#FF00FF';
    ctx.lineWidth = 2;
    ctx.stroke();
  }

  // VS text
  ctx.font = `900 11px ${ARCADE_UI_FONT}`;
  ctx.fillStyle = '#FFFFFF';
  ctx.textAlign = 'center';
  ctx.fillText('VS', centerX, y + 5);
}

/**
 * Render fight announcement
 */
export function renderAnnouncement(
  ctx: CanvasRenderingContext2D,
  text: string,
  subtext?: string,
  progress = 1
): void {
  const alpha = progress < 0.2 ? progress / 0.2 : progress > 0.8 ? 1 - (progress - 0.8) / 0.2 : 1;
  const scale = 1 + (1 - progress) * 0.2;

  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.translate(CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
  ctx.scale(scale, scale);

  // Main text
  ctx.font = 'bold 64px "Courier New", monospace';
  ctx.fillStyle = '#FF00FF';
  ctx.textAlign = 'center';
  ctx.shadowColor = '#FF00FF';
  ctx.shadowBlur = 20;
  ctx.fillText(text, 0, 0);

  // Subtext
  if (subtext) {
    ctx.font = '24px "Courier New", monospace';
    ctx.fillStyle = '#00F5FF';
    ctx.shadowColor = '#00F5FF';
    ctx.fillText(subtext, 0, 40);
  }

  ctx.restore();
}

/**
 * Render full fight scene
 */
export function renderFightScene(
  ctx: CanvasRenderingContext2D,
  fightState: FightState,
  camera: Camera,
  presentation: FightPresentationOptions = {}
): void {
  const screenFeedbackScale = Math.max(0, Math.min(1, presentation.screenFeedbackScale ?? 1));
  const fighterFlashScale = Math.max(0, Math.min(1, presentation.fighterFlashScale ?? 1));
  const graphicsProfile = resolveFightGraphicsProfile(presentation);
  const cameraTransform = createArcadeCameraTransform({
    x: CANVAS_WIDTH / 2,
    y: CANVAS_HEIGHT / 2,
    zoom: camera.zoom,
    shakeX: camera.shakeOffsetX,
    shakeY: camera.shakeOffsetY,
    viewportWidth: CANVAS_WIDTH,
    viewportHeight: CANVAS_HEIGHT,
    anchorX: 0.5,
    anchorY: 0.5,
  });
  ctx.save();
  cameraTransform.applyToCanvas(ctx);

  // Background
  if (presentation.renderBackground !== false) {
    renderBackground(ctx, camera, fightState.frameCount, graphicsProfile);
  }

  // Arena
  if (presentation.renderArena !== false) {
    renderArena(ctx, camera, graphicsProfile, fightState.frameCount);
  }

  // Fighters (sorted by lane for proper layering)
  const fighters = [fightState.player1, fightState.player2];
  fighters.sort((a, b) => a.lane - b.lane);

  for (const effect of fightState.visualEffects.filter((effect) => effect.layer === 'behind')) {
    renderVisualEffect(ctx, effect);
  }

  for (const fighter of fighters) {
    renderAttackTelegraph(ctx, fighter, fightState.frameCount);
    for (const effect of collectAmbientEffectsForFighter(fighter, fightState.frameCount)) {
      if (effect.layer === 'behind') {
        renderAmbientEffect(ctx, effect);
      }
    }
    if (presentation.renderActors !== false) {
      renderFighter(ctx, fighter, camera, fightState.frameCount, fighterFlashScale);
    }
    for (const effect of collectAmbientEffectsForFighter(fighter, fightState.frameCount)) {
      if (effect.layer === 'front') {
        renderAmbientEffect(ctx, effect);
      }
    }
  }

  for (const effect of fightState.visualEffects.filter((effect) => effect.layer === 'front')) {
    renderVisualEffect(ctx, effect);
  }

  fightState.particlePool.render(ctx);
  renderFightForeground(ctx, camera, fightState.frameCount, graphicsProfile, fightState);

  if (fightState.hitFreezeFrames > 0) {
    ctx.save();
    ctx.globalAlpha = Math.min(0.14, fightState.hitFreezeFrames * 0.04) * screenFeedbackScale;
    ctx.fillStyle = '#FFFFFF';
    ctx.fillRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);
    ctx.restore();
  }

  ctx.restore();

  // Render screen effects on top of everything
  for (const screenEffect of fightState.screenEffects) {
    ctx.save();
    ctx.globalAlpha = screenFeedbackScale;
    screenEffect.render(ctx);
    ctx.restore();
  }

  if (presentation.renderScreenFeedback !== false) {
    ctx.save();
    ctx.globalAlpha = screenFeedbackScale;
    renderCombatScreenFeedback(ctx, fightState);
    ctx.restore();
  }
  renderFightStageCue(ctx, fightState.frameCount, graphicsProfile, fightState);

  if (presentation.renderHud !== false) {
    // HUD
    const p1Char = CHARACTERS[fightState.player1.characterId as keyof typeof CHARACTERS];
    const p2Char = CHARACTERS[fightState.player2.characterId as keyof typeof CHARACTERS];

    renderHudChrome(ctx);

    renderHealthBar(
      ctx,
      50,
      36,
      300,
      18,
      fightState.player1.health,
      fightState.player1.stats.maxHealth,
      p1Char?.colors.primary ?? '#00F5FF',
      p1Char?.name ?? 'P1',
      false
    );

    renderHealthBar(
      ctx,
      CANVAS_WIDTH - 350,
      36,
      300,
      18,
      fightState.player2.health,
      fightState.player2.stats.maxHealth,
      p2Char?.colors.primary ?? '#FF00FF',
      p2Char?.name ?? 'P2',
      true
    );

    renderSpecialMeter(
      ctx,
      fightState.player1,
      50,
      61,
      300,
      p1Char?.colors.accent ?? '#39FF14',
      false
    );
    renderSpecialMeter(
      ctx,
      fightState.player2,
      CANVAS_WIDTH - 350,
      61,
      300,
      p2Char?.colors.accent ?? '#FF9F1C',
      true
    );

    // Timer
    renderTimer(ctx, fightState.round.time, fightState.round.number);

    // Round indicator
    renderRoundIndicator(ctx, fightState.scores[0] ?? 0, fightState.scores[1] ?? 0, 2);

    // Combo displays
    if (fightState.combos[0]?.count > 1) {
      renderComboDisplay(ctx, 150, 150, fightState.combos[0].count, '#00F5FF');
    }
    if (fightState.combos[1]?.count > 1) {
      renderComboDisplay(ctx, CANVAS_WIDTH - 150, 150, fightState.combos[1].count, '#FF00FF');
    }
  }
}
